import{_ as p,r as s,o,c,e as n,a as l,s as d}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"图像调整大小 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"介绍","slug":"介绍","link":"#介绍","children":[]},{"level":2,"title":"调整磁盘上的文件大小","slug":"调整磁盘上的文件大小","link":"#调整磁盘上的文件大小","children":[{"level":3,"title":"调整大小参数","slug":"调整大小参数","link":"#调整大小参数","children":[]},{"level":3,"title":"可用模式","slug":"可用模式","link":"#可用模式","children":[]}]},{"level":2,"title":"调整文件大小并输出到浏览器","slug":"调整文件大小并输出到浏览器","link":"#调整文件大小并输出到浏览器","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/extend/services/resizer.md","filePath":"3.x/zh-cn/extend/services/resizer.md"}'),i={name:"3.x/zh-cn/extend/services/resizer.md"};function r(u,a,k,h,g,m){const e=s("pre-heading"),t=s("post-heading");return o(),c("div",null,[n(e),a[0]||(a[0]=l("h1",null,"图像调整大小",-1)),n(t),a[1]||(a[1]=d(`<h2 id="介绍"><a href="#介绍" class="header-anchor">#</a> 介绍</h2><p>October CMS 附带了一个图像调整器，可让你更改支持的图像的形状和大小。</p><h2 id="调整磁盘上的文件大小"><a href="#调整磁盘上的文件大小" class="header-anchor">#</a> 调整磁盘上的文件大小</h2><p>要调整图像大小，请使用 <code>Resizer</code> 门面上的 <code>open</code> 方法指向文件路径。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/image.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以从<a href="./request-input.html">页面请求输入</a>中传入上传的文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;field_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要调整图像大小，请在对象上调用 <code>resize</code> 方法来执行调整大小操作。第一个参数是图像宽度，第二个参数是图像高度，第三个参数是调整大小参数的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>宽度和高度参数也是可选的，例如，要使用现有宽度仅调整高度，请将第二个参数传递为 <code>null</code>。然后根据 <code>mode</code> 选项，使用原始图像比例计算此值（自动等比缩放）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>最后，使用 <code>save</code> 方法将调整大小后的图像保存到新位置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/new/file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="调整大小参数"><a href="#调整大小参数" class="header-anchor">#</a> 调整大小参数</h3><p>选项数组中支持以下元素：</p><div class="table"><table tabindex="0"><thead><tr><th>键</th><th>描述</th><th>默认值</th><th>选项</th></tr></thead><tbody><tr><td><code>mode</code></td><td>图像应如何适应尺寸</td><td><code>auto</code></td><td><code>exact</code>、<code>portrait</code>、<code>landscape</code>、<code>auto</code>、<code>fit</code> 或 <code>crop</code></td></tr><tr><td><code>offset</code></td><td>调整大小图像的裁剪偏移量</td><td><code>[0,0]</code></td><td>[左, 上]</td></tr><tr><td><code>quality</code></td><td>调整大小后图像的质量</td><td><code>90</code></td><td><code>0-100</code></td></tr><tr><td><code>sharpen</code></td><td>图像锐化量</td><td><code>0</code></td><td><code>0-100</code></td></tr></tbody></table></div><h3 id="可用模式"><a href="#可用模式" class="header-anchor">#</a> 可用模式</h3><p><code>mode</code> 选项允许你指定图像应如何调整大小。可用的模式如下：</p><div class="table"><table tabindex="0"><thead><tr><th>模式</th><th>描述</th></tr></thead><tbody><tr><td><code>auto</code></td><td>根据图像的方向自动在 <code>portrait</code> 和 <code>landscape</code> 之间选择</td></tr><tr><td><code>exact</code></td><td>调整为给定的精确尺寸，不保持宽高比</td></tr><tr><td><code>portrait</code></td><td>调整为给定的高度，并调整宽度以保持宽高比</td></tr><tr><td><code>landscape</code></td><td>调整为给定的宽度，并调整高度以保持宽高比</td></tr><tr><td><code>crop</code></td><td>在尽可能多地将图像放入给定尺寸后，裁剪为给定尺寸</td></tr><tr><td><code>fit</code></td><td>将图像放入给定的最大尺寸内，保持宽高比</td></tr></tbody></table></div><h2 id="调整文件大小并输出到浏览器"><a href="#调整文件大小并输出到浏览器" class="header-anchor">#</a> 调整文件大小并输出到浏览器</h2><p><code>System\\Classes\\ResizeImages</code> 类可用于调整图像大小并通过 URL 提供：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token variable">$image</span><span class="token punctuation">,</span> <span class="token variable">$width</span><span class="token punctuation">,</span> <span class="token variable">$height</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果你正在调整媒体库项目的大小，应使用 <code>Media\\Classes\\MediaLibrary</code> 类和 <code>url</code> 方法解析媒体路径。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Media<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MediaLibrary</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;relative/path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token variable">$image</span><span class="token punctuation">,</span> <span class="token variable">$width</span><span class="token punctuation">,</span> <span class="token variable">$height</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>还有一个 <code>|resize</code> <a href="./../../markup/filter/resize.html">标记过滤器</a>可用于在主题中调整图像大小。</p></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../markup/filter/resize.html">调整大小过滤器</a></li><li><a href="./../../markup/filter/media.html">媒体过滤器</a></li></ul></div>`,27))])}const b=p(i,[["render",r]]);export{f as __pageData,b as default};
